// --- Webhook auth ---
const headers = $input.first().json.headers || {};
const secret = headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || '';
if (secret !== 'YOUR_WEBHOOK_SECRET') {
  throw new Error('Unauthorized: invalid or missing X-Webhook-Secret header');
}

const data = $input.first().json.body || $input.first().json;
const now  = new Date().toISOString();

const service     = (data.service     || data.serviceInterest || 'General Inquiry').trim();
const leadSource  = (data.leadSource  || data.lead_source    || 'Website').trim();

// Service-specific info blocks
const serviceInfo = {
  'Botox': {
    tagline: 'Natural results that last 3–4 months',
    details: 'Botox treatments take just 15–20 minutes with zero downtime. Results begin appearing within 3–7 days and last 3–4 months. Perfect for forehead lines, crow\'s feet, and frown lines.',
    price: 'Starting from $10–$14/unit',
    cta: 'Book a free 15-minute consultation and we\'ll map out exactly what you need.'
  },
  'Filler': {
    tagline: 'Restore volume and definition — instantly',
    details: 'Dermal fillers add immediate volume and contour to lips, cheeks, and jawline. Results are visible right away and last 12–18 months depending on the area and product used.',
    price: 'Starting from $600 per syringe',
    cta: 'Book a complimentary consultation to discuss your goals and see a preview of your results.'
  },
  'Laser Hair Removal': {
    tagline: 'Permanent reduction in 6–8 sessions',
    details: 'Laser hair removal targets hair follicles to permanently reduce unwanted hair. Most clients complete a course of 6–8 treatments spaced 4–6 weeks apart. Safe for all skin types with our advanced technology.',
    price: 'Single session or package pricing available',
    cta: 'Book a free patch test and consultation — we\'ll give you a personalised treatment plan and package price.'
  },
  'HydraFacial': {
    tagline: 'The world\'s most popular skin treatment',
    details: 'HydraFacial deeply cleanses, exfoliates, and hydrates your skin in a single 45-minute session. No downtime, instant glow, suitable for all skin types. Best results with monthly treatments.',
    price: 'From $180 per session',
    cta: 'Book your first HydraFacial today — most clients leave glowing.'
  },
  'Microneedling': {
    tagline: 'Stimulate collagen. Transform your skin.',
    details: 'Microneedling creates micro-channels in the skin to stimulate natural collagen production. Reduces fine lines, scarring, and texture. A course of 3–6 treatments produces the best results.',
    price: 'From $300 per session',
    cta: 'Book a consultation and skin analysis — we\'ll design a treatment plan tailored to your skin goals.'
  },
  'General Inquiry': {
    tagline: 'Let\'s find the right treatment for you',
    details: 'We offer a full range of medical aesthetic treatments including injectables (Botox, fillers), laser treatments, skin rejuvenation, and body contouring. Every treatment plan starts with a complimentary consultation.',
    price: 'Treatments start from $150',
    cta: 'Book a free 15-minute consultation — no pressure, just an honest conversation about your goals.'
  }
};

const info = serviceInfo[service] || serviceInfo['General Inquiry'];

return [{
  json: {
    clientEmail:     (data.email    || data.clientEmail    || '').trim(),
    clientName:      (data.name     || data.clientName     || '').trim(),
    phoneNumber:     (data.phone    || data.phoneNumber    || '').trim(),
    service,
    leadSource,
    referralName:    (data.referralName || data.referral_name || '').trim(),
    serviceTagline:  info.tagline,
    serviceDetails:  info.details,
    servicePrice:    info.price,
    serviceCta:      info.cta,
    nowIso: now,
    status: 'New Inquiry'
  }
}];
